package com.laptopshop.controller; import com.laptopshop.dto.*; import com.laptopshop.entity.*; import com.laptopshop.exception.*; import com.laptopshop.service.*; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.math.BigDecimal;
@Controller @RequestMapping("/admin/laptops") public class LaptopController { private final LaptopService service; private final CategoryService categories; private final BrandService brands; public LaptopController(LaptopService s,CategoryService c,BrandService b){service=s;categories=c;brands=b;}
 private void options(Model m){m.addAttribute("categories",categories.getAllCategories());m.addAttribute("brands",brands.getAllBrands());}
 @GetMapping public String list(@RequestParam(required=false) String keyword,@RequestParam(required=false) Integer categoryId,@RequestParam(required=false) Integer brandId,@RequestParam(required=false) BigDecimal minPrice,@RequestParam(required=false) BigDecimal maxPrice,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="id") String sortBy,@RequestParam(defaultValue="asc") String direction,Model m){var p=service.filterLaptops(keyword,categoryId,brandId,minPrice,maxPrice,page,size,sortBy,direction);options(m);m.addAttribute("laptopPage",p);m.addAttribute("keyword",keyword);m.addAttribute("categoryId",categoryId);m.addAttribute("brandId",brandId);m.addAttribute("minPrice",minPrice);m.addAttribute("maxPrice",maxPrice);m.addAttribute("sortBy",sortBy);m.addAttribute("direction",direction);return "laptops/list";}
 @GetMapping("/add") public String add(Model m){m.addAttribute("laptopDTO",new LaptopDTO());m.addAttribute("isEdit",false);options(m);return "laptops/form";}
 @PostMapping("/add") public String create(@Valid @ModelAttribute LaptopDTO laptopDTO,BindingResult br,Model m,RedirectAttributes ra){if(br.hasErrors()){m.addAttribute("isEdit",false);options(m);return "laptops/form";}try{service.createLaptop(laptopDTO);ra.addFlashAttribute("successMessage","Thêm laptop thành công");return "redirect:/admin/laptops";}catch(RuntimeException e){m.addAttribute("errorMessage",e.getMessage());m.addAttribute("isEdit",false);options(m);return "laptops/form";}}
 @GetMapping("/edit/{id}") public String edit(@PathVariable Integer id,Model m,RedirectAttributes ra){try{Laptop l=service.getLaptopById(id);LaptopDTO d=new LaptopDTO();d.setId(l.getId());d.setSku(l.getSku());d.setName(l.getName());d.setCategoryId(l.getCategory().getId());d.setBrandId(l.getBrand().getId());d.setCpu(l.getCpu());d.setRamGb(l.getRamGb());d.setStorageGb(l.getStorageGb());d.setGpu(l.getGpu());d.setScreenSize(l.getScreenSize());d.setOperatingSystem(l.getOperatingSystem());d.setColor(l.getColor());d.setPurchasePrice(l.getPurchasePrice());d.setSalePrice(l.getSalePrice());d.setStockQuantity(l.getStockQuantity());d.setImageUrl(l.getImageUrl());d.setDescription(l.getDescription());d.setIsActive(l.getIsActive());m.addAttribute("laptopDTO",d);m.addAttribute("isEdit",true);options(m);return "laptops/form";}catch(RuntimeException e){ra.addFlashAttribute("errorMessage",e.getMessage());return "redirect:/admin/laptops";}}
 @PostMapping("/edit/{id}") public String update(@PathVariable Integer id,@Valid @ModelAttribute LaptopDTO laptopDTO,BindingResult br,Model m,RedirectAttributes ra){if(br.hasErrors()){m.addAttribute("isEdit",true);options(m);return "laptops/form";}try{service.updateLaptop(id,laptopDTO);ra.addFlashAttribute("successMessage","Cập nhật laptop thành công");return "redirect:/admin/laptops";}catch(RuntimeException e){m.addAttribute("errorMessage",e.getMessage());m.addAttribute("isEdit",true);options(m);return "laptops/form";}}
 @PostMapping("/delete/{id}") public String delete(@PathVariable Integer id,RedirectAttributes ra){try{service.deleteLaptop(id);ra.addFlashAttribute("successMessage","Xóa laptop thành công");}catch(RuntimeException e){ra.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/admin/laptops";}}
